setup:
CREATE TABLE customers (
    id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    full_name text,
    phone text,
    signed_up text
);
INSERT INTO customers (full_name, phone, signed_up) VALUES
    ('Ana Lopez', '555-0101', '2025-03-01'),
    ('Ben Carter', '555-0102', '2025-03-14'),
    ('Chloe Kim', '555-0103', '2025-04-02'),
    ('Dev Patel', '555-0104', '2025-04-20');
CREATE TABLE old_customers (
    id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    full_name text
);
INSERT INTO old_customers (full_name) VALUES
    ('Ana Lopez'),
    ('Gus Moreno');

